import { Pressable, Text, View } from 'react-native';

type Props = { name: string; price: string; soldOut?: boolean; onPress: () => void };

export function DishCard({ name, price, soldOut = false, onPress }: Props) {
  return (
    <Pressable
      onPress={onPress}
      disabled={soldOut}
      className="flex-row items-center justify-between rounded-2xl bg-white p-4 active:opacity-70 dark:bg-zinc-900"
    >
      <View className="gap-1">
        <Text className="text-base font-semibold text-zinc-900 dark:text-white">{name}</Text>
        <Text className="text-sm text-zinc-500">{price}</Text>
      </View>
      {soldOut && <Text className="text-xs font-medium uppercase text-red-600">Esgotado</Text>}
    </Pressable>
  );
}

