import { cva, type VariantProps } from 'class-variance-authority';
import { twMerge } from 'tailwind-merge';

const button = cva('inline-flex items-center justify-center rounded-lg font-medium disabled:opacity-50', {
  variants: {
    variant: {
      primary: 'bg-brand-500 text-white hover:bg-brand-600',
      secondary: 'bg-zinc-100 text-zinc-900 hover:bg-zinc-200',
      ghost: 'bg-transparent text-zinc-700 hover:bg-zinc-100',
    },
    size: { sm: 'h-8 px-3 text-sm', md: 'h-10 px-4', lg: 'h-12 px-6 text-lg' },
  },
  defaultVariants: { variant: 'primary', size: 'md' },
});

type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof button>;

export function Button({ variant, size, className, ...props }: ButtonProps) {
  // twMerge resolve conflitos: um className="px-8" vindo de fora vence o px-4 da variante
  return <button className={twMerge(button({ variant, size }), className)} {...props} />;
}

import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn } from 'storybook/test';
import { Button } from './Button';

const meta = {
  component: Button,
  tags: ['autodocs'], // gera a página de documentação com as props
  args: { children: 'Fazer pedido', onClick: fn() },
} satisfies Meta<typeof Button>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Primary: Story = {};
export const Secondary: Story = { args: { variant: 'secondary' } };
export const Disabled: Story = { args: { disabled: true } };

export const Clicked: Story = {
  play: async ({ args, canvas, userEvent }) => {
    await userEvent.click(canvas.getByRole('button', { name: 'Fazer pedido' }));
    await expect(args.onClick).toHaveBeenCalled();
  },
};

import { Pressable } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

type Props = { favorite: boolean; dishName: string; onToggle: () => void };

export function FavoriteButton({ favorite, dishName, onToggle }: Props) {
  return (
    <Pressable
      onPress={onToggle}
      role="button"
      aria-label={favorite ? `Remover ${dishName} dos favoritos` : `Favoritar ${dishName}`}
      aria-selected={favorite}
      hitSlop={12} // amplia a área de toque além do ícone de 24 pt
      className="p-2"
    >
      {/* o Pressable acessível agrupa os filhos: o leitor de tela lê só o rótulo do botão */}
      <Ionicons name={favorite ? 'heart' : 'heart-outline'} size={24} />
    </Pressable>
  );
}

export function EmailField({ error }: { error?: string }) {
  return (
    <div>
      <label htmlFor="email">E-mail</label>
      <input
        id="email"
        type="email"
        autoComplete="email"
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? 'email-error' : undefined}
      />
      {/* role="alert" faz o leitor de tela anunciar o erro quando ele aparece */}
      {error && (
        <p id="email-error" role="alert" className="text-sm text-red-700">
          {error}
        </p>
      )}
    </div>
  );
}
